          "points": null
        },
        {
          "criterion": "Competência 4: mecanismos linguísticos de argumentação",
          "description": "Avalia o uso de recursos linguísticos que promovam a articulação entre palavras, frases e parágrafos.",
          "points": null
        },
        {
          "criterion": "Competência 5: proposta de intervenção",
          "description": "Avalia a elaboração de uma proposta de intervenção relacionada ao problema discutido e articulada à argumentação, com respeito aos direitos humanos.",
          "points": null
        }
      ],
      "keyPoints": [
        "Delimitar uma tese sobre os obstáculos à acessibilidade digital de pessoas idosas no Brasil.",
